      renwu = "npc",
      role1 = 1112000,
      role2 = 1112104,
      role3 = 102201,
      role5 = 1112402,
      sentence = "All those years ago when I rescued you outside the city gate, that arrow plunged into the flesh and bones of your back. When the doctor pulled it out for you, he said that even for the toughest of men to be shot like this, they would cry out in pain.",
      voice = 2,
