      idx = 1,
      male = 1,
      music = "27_Double_Seventh",
      renming = "Victor",
      renwu = "npc",
      role1 = 1112000,
      role2 = 1112104,
      role3 = 102201,
      role5 = 1112402,
      ruchang = 9,
      sentence = "When you had nightmares, you were like that too... As long as I held your hand, you could sleep soundly.",
      voice = 2,
      next = {42}
    },
    [42] = {
      beijing = 8021,
      dialog = 3,
      music = "27_Double_Seventh",
      renwu = "npc",
      sentence = "That was true. Sleeping in a military tent, one could always hear the sound of weapons clinking, and in my dreams, visions of my father lying atop a heap of corpses would arise unbidden.",
      next = {43}
    },
    [43] = {
      beijing = 8021,
      dialog = 3,
      music = "27_Double_Seventh",
      renwu = "npc",
      sentence = "I dreamed that a blizzard had blown down from the sky, and no one could give me refuge from the storm.",
      next = {44}
    },
    [44] = {
      beijing = 8021,
      dialog = 3,
      music = "27_Double_Seventh",
      renwu = "npc",
      sentence = "Then, Victor took hold of my hand — He would always come in the night and guard over me in the stead of the soldiers on night shift. When it was rainy, he would fan away the flies. When snowy, he'd add coals to the fire.",
      next = {45}
    },
    [45] = {
