    },
    [47] = {
      beijing = 8021,
      dialog = 3,
      music = "27_Double_Seventh",
      renwu = "npc",
      sentence = "It wasn't any nice wine in the jug, and the cold wine tasted a bit dull against the cold weather. But Victor didn't mind. He tilted his head back and took a swig.",
