      music = "27_Double_Seventh",
      renming = "Victor",
      renwu = "npc",
      role1 = 1111000,
      role2 = 1111103,
      role3 = 101201,
      ruchang = -1,
      sentence = "With a new emperor taking the throne, a sacrificial offering ceremony is unavoidable.",
      voice = 2,
      next = {49}
    },
    [49] = {
      beijing = 8021,
      dialog = 2,
      idx = 1,
