      music = "27_Double_Seventh",
      renming = "Victor",
      renwu = "npc",
      role1 = 1111000,
      role2 = 1111103,
      role3 = 101201,
      sentence = "And you know very well that such a ceremony is always performed by the emperor and empress together. For a hundred years, there have been no exceptions.",
      voice = 2,
      next = {50}
    },
    [50] = {
      beijing = 8021,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "27_Double_Seventh",
      renming = "Victor",
      renwu = "npc",
      role1 = 1111000,
