      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "All these years as I charged on the forefront, rushing into the enemy's ranks, he was always there behind me, keeping me safe, never letting me fall into danger. When the winds and snows came, I was never left out in the cold alone.",
